#pragma once

#include "pathresult.h"

// Stores the calculated route distance
void pathresult::setDistance(int distance)
{
    totalDistance = distance;
}

// Stores the calculated route
void pathresult::setRoute(
    const std::vector<std::string>& route)
{
    this->route = route;
}

// Returns the total route distance
int pathresult::getDistance() const
{
    return totalDistance;
}

// Returns the route generated by the pathfinding algorithm
const std::vector<std::string>&
pathresult::getRoute() const
{
    return route;
}